  async function enviarChavePix(i:Interaction,guild:string,o:Pedido,automatico:boolean){
    if(!i.isRepliable()||o.cliente!==i.user.id||o.estado!=='pendente'||o.formaPagamento?.tipo!=='pix_manual')throw Error('Chave PIX indisponível para este pedido.');
    const mensagem=mensagemChavePix(o.formaPagamento);
    if(automatico&&!store.marcarChavePix(guild,o.id,i.user.id))return;
    const ticket=o.canalEntrega==='ticket'&&o.ticket?await i.guild?.channels.fetch(o.ticket).catch(()=>null):null;
    const privado=ticket?.type===ChannelType.GuildText&&!ticket.permissionsFor(i.guild!.roles.everyone)?.has(P.ViewChannel);
    const noTicket=privado&&ticket.id===i.channelId;
    try{
      if(noTicket)await ticket.send({content:'**Chave PIX do pedido '+o.id+'**\n'+mensagem,allowedMentions:{parse:[]}});
      else await i.followUp({content:'**Chave PIX do pedido '+o.id+'**\n'+mensagem+'\nVisível somente para você.',flags:MessageFlags.Ephemeral,allowedMentions:{parse:[]}});
    }catch{if(automatico)store.liberarChavePix(guild,o.id,i.user.id);throw Error('Não consegui mostrar a chave PIX com privacidade. Use Copiar chave PIX novamente.');}
    if(privado&&!noTicket)try{await ticket.send({content:'**Chave PIX do pedido '+o.id+'**\n'+mensagem,allowedMentions:{parse:[]}});}catch{console.warn('Chave PIX não enviada ao ticket do pedido '+o.id);}
    if(noTicket)await i.followUp({content:'Chave PIX enviada no ticket privado.',flags:MessageFlags.Ephemeral});
  }
  const entregando=comercio.travas,abrindo=new Set<string>();
  const pedidosGerais=(o:Pedido)=>!itensDoPedido(o).some(item=>item.botEstoque);
  async function ticketPendente(guild:Guild,o:Pedido){
   if((!pedidosGerais(o)&&!store.obter(guild.id).config.ticketsBotsEstoque)||o.canalEntrega!=='ticket'||!['pendente','aprovado'].includes(o.estado)||o.entregue||!atendimento)return;
   const lock=guild.id+':'+o.id;if(abrindo.has(lock))return;abrindo.add(lock);
   try{
    const atual=store.obter(guild.id).pedidos[o.id];if(!atual||!['pendente','aprovado'].includes(atual.estado))return;
    // Um ticket já vinculado não é uma criação pendente. Mesmo se o canal foi fechado ou
    // excluído, a sincronização não deve recriá-lo; a reabertura exige ação explícita.
    if(atual.ticket)return;
    const canal=await atendimento.abrirVenda(guild,o.cliente,o.id);store.vincularTicket(guild.id,o.id,canal,true);if(store.obter(guild.id).pedidos[o.id]?.estado==='cancelado'){await limparTicketCancelado(guild,store.obter(guild.id).pedidos[o.id]!);return;}
    const ch=await guild.channels.fetch(canal);if(ch?.type===ChannelType.GuildText)await ch.send(tela(guild.id,emojiTexto('tickets')+' Pedido '+o.id,'**'+o.nome+'** · **'+dinheiro(o.total)+'**\nAguardando pagamento e conferência da equipe. A entrega só será liberada após a aprovação.\nSe o pedido for cancelado ou expirar, este ticket será encerrado.\nEquipe: use /gerenciarpedido neste ticket para abrir a gestão privada da compra.',[row(b('acompanhar:'+o.id,'Meu pedido','historico'),b('gestaopedido:'+o.id,'Equipe: gerenciar pedido','equipe'))]));
   }finally{abrindo.delete(lock);}
  }
  async function limparTicketCancelado(guild:Guild,o:Pedido){if((pedidosGerais(o)||store.obter(guild.id).config.ticketsBotsEstoque)&&o.estado==='cancelado'&&!o.ticketCancelamentoConcluido&&o.ticket&&atendimento?.cancelarVenda){await atendimento.cancelarVenda(guild,o.cliente,o.id,o.ticket);store.marcarTicketCancelado(guild.id,o.id,o.ticket);}}
  const vitrinesGerais=new Map<string,string>();let sincronizando=false;
  async function sincronizarGeral(){if(contextoAtual()?.parando||sincronizando||!bot.isReady())return;sincronizando=true;try{for(const guild of bot.guilds.cache.values()){
   const expirados=store.expirar(guild.id,!store.obter(guild.id).config.ticketsBotsEstoque);for(const id of expirados){const o=store.obter(guild.id).pedidos[id]!;void bot.users.fetch(o.cliente).then(u=>u.send({content:emojiTexto('aviso')+' O prazo do pedido **'+id+'** expirou. Nenhuma cobrança automática foi feita. Você pode criar outro pedido.'})).catch(()=>{});}const loja=store.obter(guild.id);
   for(const o of Object.values(loja.pedidos))try{if(o.estado==='cancelado')await limparTicketCancelado(guild,o);else{await ticketPendente(guild,o);if(pedidosGerais(o)&&o.estado==='aprovado'&&o.canalEntrega==='ticket'&&!o.entregue&&itensDoPedido(o).some(i=>i.automatico&&!i.entregue))await comercio.automaticos(guild,o.id);}}catch{console.warn('Ticket de pedido aguarda nova tentativa; confira as configurações e permissões de vendas.');}
   for(const p of Object.values(store.obter(guild.id).produtos).filter(p=>!p.botEstoque&&p.publicacoes.length)){
    const key=guild.id+':'+p.id,assinatura=JSON.stringify(p);if(vitrinesGerais.get(key)===assinatura)continue;
    const falhas=await atualizarVitrines({guild,guildId:guild.id},p);if(!falhas)vitrinesGerais.set(key,assinatura);
   }
   await atualizarEstoqueAutomatico(guild,store).catch(()=>console.warn('Atualização automática de estoque aguarda nova tentativa.'));
  }}finally{sincronizando=false;}}
  const syncGeralRastreado=rastrearBot(sincronizarGeral);
  const syncTimer=intervaloBot(()=>{void syncGeralRastreado().catch(()=>console.warn('Sincronização da loja aguarda nova tentativa.'));},15000);syncTimer.unref();
